-- (maks 20 foto) -> laporan 0 foto. Skrip ini MENEMPEL ke-57 URL itu lewat RPC tambah_foto_dokumentasi per 20 (berlaku
-- utk RPC lama maupun baru; URL dobel diabaikan - aman diulang). Nama file = nama di R2 (nama asli dari HP tidak tersimpan).
-- Ditandai dipulihkan=2026-10-19 di tiap objek foto. BAGIAN 1 dry-run -> BAGIAN 2 eksekusi -> BAGIAN 3 rollback.
-- ============================================================================================

-- BAGIAN 1: DRY-RUN (foto sekarang harus 0, laporan ada)
select id, nama_lokasi, operator_nama, jsonb_array_length(coalesce(foto, '[]'::jsonb)) as foto_sekarang from public.proyek_luar where id = 14;

